function estimateExtrusionGrams(text,types){
  // Estimación auxiliar: suma movimientos positivos de extrusión por herramienta.
  const toolLengths={};let tool=0,absoluteE=true;const lastE={};const activeType=(types||[]).join(' ').toUpperCase();
  for(const raw of text.split(/\r?\n/)){const line=raw.split(';')[0].trim();if(!line)continue;if(/^M82\b/i.test(line)){absoluteE=true;continue}if(/^M83\b/i.test(line)){absoluteE=false;continue}const tm=line.match(/^T(\d+)\b/i);if(tm){tool=Number(tm[1]);if(lastE[tool]===undefined)lastE[tool]=0;continue}if(/^G92\b/i.test(line)){const em=line.match(/(?:^|\s)E(-?\d+(?:\.\d+)?)/i);if(em)lastE[tool]=Number(em[1]);continue}if(!/^(?:G0|G1)\b/i.test(line))continue;const em=line.match(/(?:^|\s)E(-?\d+(?:\.\d+)?)/i);if(!em)continue;const e=Number(em[1]);if(!Number.isFinite(e))continue;let delta=0;if(absoluteE){if(lastE[tool]===undefined)lastE[tool]=0;delta=e-lastE[tool];lastE[tool]=e;}else delta=e;if(delta>0)toolLengths[tool]=(toolLengths[tool]||0)+delta;}
  const keys=Object.keys(toolLengths).filter(k=>toolLengths[k]>1);if(!keys.length)return [];let density=1.24;if(/PETG/.test(activeType))density=1.27;else if(/ABS|ASA/.test(activeType))density=1.04;else if(/TPU/.test(activeType))density=1.21;else if(/PA|NYLON/.test(activeType))density=1.14;else if(/PLA/.test(activeType))density=1.24;const area=Math.PI*Math.pow(1.75/2,2);return keys.sort((a,b)=>Number(a)-Number(b)).map(k=>({tool:Number(k),grams:toolLengths[k]*area/1000*density}));
}
function readFileText(file){return new Promise((resolve,reject)=>{if(!file){reject(new Error(window.PCP_I18N.t('No se recibió ningún archivo.')));return;}if(file.size===0){reject(new Error(window.PCP_I18N.t('El archivo seleccionado está vacío (0 bytes).')));return;}if(file&&typeof file.text==='function'){file.text().then(text=>resolve(String(text||'').replace(/^\uFEFF/,''))).catch(()=>readWithFileReader(file,resolve,reject));return;}readWithFileReader(file,resolve,reject);});}

// Registro temprano del selector G-code: evita que un fallo de inicialización de otra pestaña deje el botón manual sin manejador.
$('gcodeFile').addEventListener('change',async e=>{const f=e.target.files&&e.target.files[0];if(!f)return;currentFile=f.name;try{if(/\.bgcode$/i.test(f.name))throw new Error('Has seleccionado un .bgcode, que es binario. En Snapmaker Orca usa Exportar G-code y selecciona .gcode.');if(!/\.(gcode|gco|gc|txt)$/i.test(f.name))throw new Error('Formato no reconocido: '+f.name+'. Selecciona un archivo .gcode, .gco o .gc.');const text=await readFileText(f);if(!text||!text.trim())throw new Error('El archivo se ha abierto, pero está vacío o no contiene texto legible. Tamaño: '+f.size+' bytes.');try{parseGcode(text,f.name);}catch(parseErr){console.error('Print Cost & Profit: fallo al interpretar G-code',parseErr);throw new Error('El archivo se leyó, pero falló el análisis del G-code: '+(parseErr&&parseErr.message?parseErr.message:String(parseErr)));}}catch(err){console.error('Print Cost & Profit: error al cargar G-code',err);const msg=err&&err.message?err.message:String(err);toast(msg);$('fileMeta').innerHTML='<span class="warn"><strong>No se pudo cargar el archivo.</strong><br>'+escapeHtml(msg)+'<br>Archivo: '+escapeHtml(f.name)+' ('+f.size+' bytes). Si persiste, adjunta este G-code en el chat para adaptar el lector.</span>';currentFile='';}finally{e.target.value='';}});
function readWithFileReader(file,resolve,reject){if(typeof FileReader==='undefined'){reject(new Error('Este navegador no permite leer archivos locales. Prueba abrirlo con Opera o Chrome actualizados.'));return;}const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||'').replace(/^\uFEFF/,''));reader.onerror=()=>reject(new Error('El navegador no pudo leer el archivo (FileReader error). Prueba copiar el G-code a una carpeta local, por ejemplo Escritorio.'));reader.onabort=()=>reject(new Error('La lectura del archivo fue cancelada.'));try{reader.readAsText(file,'UTF-8');}catch(err){reject(new Error('No se pudo iniciar la lectura: '+(err&&err.message?err.message:String(err))));}}
