function pcpApplyDomSort(container,tableSelector,key){const cfg=PCP_SORT_CONFIG[key],sel=cfg&&$(cfg.id),table=container&&container.querySelector(tableSelector);if(!cfg||!table||!table.tBodies[0])return;if(sel&&!sel.dataset.bound){sel.addEventListener('change',()=>{localStorage.setItem('pcp_sort_'+key,sel.value);PCP_LIST_PAGES[key]=1;pcpApplyDomSort(container,tableSelector,key);const pager=container.querySelector('[data-pcp-pager="'+key+'"]');if(pager)pager.remove();if(key==='orders')pcpPaginateList(container,table,key,table.tBodies[0].rows.length);else if(key==='quotes'||key==='invoices')pcpPaginateList(container,table,key,table.tBodies[0].rows.length);});sel.dataset.bound='1';}if(sel&&localStorage.getItem('pcp_sort_'+key)!==null)sel.value=localStorage.getItem('pcp_sort_'+key);const col=sel?sel.value:'';if(col==='')return;const index=cfg.cols[col]??Number(col);const body=table.tBodies[0],rows=Array.from(body.rows);rows.sort((a,b)=>{const av=(a.cells[index]?.textContent||'').trim(),bv=(b.cells[index]?.textContent||'').trim();const an=Number(av.replace(/[^0-9,.-]/g,'').replace(',','.')),bn=Number(bv.replace(/[^0-9,.-]/g,'').replace(',','.'));return Number.isFinite(an)&&Number.isFinite(bn)&&av!==''&&bv!==''?an-bn:av.localeCompare(bv,'es',{numeric:true,sensitivity:'base'});});rows.forEach(r=>body.appendChild(r));}
function renderHistory(){const all=getHistory();const query=String($('historySearch')?.value||'').trim().toLocaleLowerCase();const sort=$('historySort')?.value||'newest';let rows=all.map((x,i)=>({x,i})).filter(({x})=>!query||[x.name,x.profile,x.file,x.jobNotes,x.notes,x.accountingType,x.accountingClient].some(v=>String(v||'').toLocaleLowerCase().includes(query)));rows.sort((a,b)=>{if(sort==='oldest')return new Date(a.x.date)-new Date(b.x.date);if(sort==='profit')return (Number(b.x.profit)||0)-(Number(a.x.profit)||0);if(sort==='cost')return (Number(a.x.cost)||0)-(Number(b.x.cost)||0);if(sort==='name')return String(a.x.name||'').localeCompare(String(b.x.name||''),'es');return new Date(b.x.date)-new Date(a.x.date)});if(!all.length){$('historyContent').className='empty';$('historyContent').textContent=window.PCP_I18N?.t('Todavía no hay tasaciones guardadas.')||'Todavía no hay tasaciones guardadas.';return}if(!rows.length){$('historyContent').className='empty';$('historyContent').textContent=window.PCP_I18N?.t('No hay tasaciones que coincidan con la búsqueda.')||'No hay tasaciones que coincidan con la búsqueda.';return}$('historyContent').className='';const table=document.createElement('table');table.className='history';table.innerHTML='<thead><tr><th>Comparar</th><th>Fecha</th><th>Imagen</th><th>Pieza</th><th>Perfil</th><th>Tiempo</th><th>Material</th><th>Coste/u.</th><th>Venta/u.</th><th>Beneficio/u.</th><th>Acciones</th></tr></thead>';const body=document.createElement('tbody');rows.forEach(({x,i})=>{const tr=document.createElement('tr');const checked=historyCompareSelection.includes(String(x.id||x.date+'|'+x.name));const key=String(x.id||x.date+'|'+x.name);tr.innerHTML=`<td><input type="checkbox" data-compare-history="${i}" aria-label="Seleccionar ${escapeHtml(x.name||'pieza')} para comparar" ${checked?'checked':''}></td><td>${escapeHtml(new Date(x.date).toLocaleDateString((window.PCP_LOCALE||'es-ES')))}</td><td>${x.image?'<img src="'+x.image+'" alt="" style="width:52px;height:52px;object-fit:contain;border-radius:6px">':'—'}</td><td>${escapeHtml(x.name||'Pieza')}</td><td>${escapeHtml(x.profile||'—')}</td><td>${Number(x.hours||0).toFixed(2)} h</td><td>${Number(x.grams||0).toFixed(1)} g</td><td>${moneyIn(x.cost,x.currency)}</td><td>${moneyIn(x.grossSale??x.sale,x.currency)}</td><td>${moneyIn(x.profit,x.currency)}</td><td><button class="btn" data-load="${i}" style="padding:5px 8px">Cargar</button> <button class="btn history-delete" data-delete-history="${i}" style="padding:5px 8px">Eliminar</button></td>`;tr.dataset.historyKey=key;body.appendChild(tr)});table.appendChild(body);$('historyContent').replaceChildren(table);pcpPaginateList($('historyContent'),table,'history',rows.length);table.querySelectorAll('[data-load]').forEach(b=>b.addEventListener('click',()=>loadHistory(Number(b.dataset.load))));table.querySelectorAll('[data-delete-history]').forEach(b=>b.addEventListener('click',async ()=>{const i=Number(b.dataset.deleteHistory);const h=getHistory();const item=h[i];if(!item)return;if(!(await window.PCPConfirm(window.PCP_I18N?.format('¿Eliminar solo la tasación de «{name}» del historial?',{name:item.name||'esta pieza'})||('¿Eliminar solo la tasación de «'+(item.name||'esta pieza')+'» del historial?'))))return;h.splice(i,1);historyCompareSelection=historyCompareSelection.filter(k=>k!==String(item.id||item.date+'|'+item.name));setHistory(h);renderHistory();toast('Tasación eliminada del historial.');}));table.querySelectorAll('[data-compare-history]').forEach(b=>b.addEventListener('change',()=>{const item=getHistory()[Number(b.dataset.compareHistory)];if(!item)return;const key=String(item.id||item.date+'|'+item.name);if(b.checked){if(historyCompareSelection.length>=2){b.checked=false;toast('Selecciona como máximo dos tasaciones.');return}if(!historyCompareSelection.includes(key))historyCompareSelection.push(key)}else historyCompareSelection=historyCompareSelection.filter(k=>k!==key); }));}
const {normalizeOrcaText}=window.PCPTextUtils;
const {normalizeHistoryNote}=window.PCPTextUtils;
function renderHistoryComparison(){const panel=$('historyCompare');const all=getHistory();const chosen=historyCompareSelection.map(k=>all.find(x=>String(x.id||x.date+'|'+x.name)===k)).filter(Boolean);if(chosen.length!==2){panel.classList.remove('hidden');panel.textContent='Selecciona exactamente dos tasaciones en la columna «Comparar» y pulsa «Comparar seleccionadas». Seleccionadas: '+chosen.length+'/2.';return}const fields=[['Pieza',x=>x.name||'Pieza'],['Fecha',x=>new Date(x.date).toLocaleString(window.PCP_LOCALE||'es-ES')],['Impresora/perfil',x=>x.profile||'—'],['Tiempo de impresión',x=>(Number(x.hours)||0).toFixed(2)+' h'],['Cantidad',x=>x.qty??1],['Filamento total',x=>(Number(x.grams)||0).toFixed(2)+' g'],['Coste por unidad',x=>moneyIn(x.cost,x.currency)],['Precio de venta por unidad',x=>moneyIn(x.grossSale??x.sale,x.currency)],['Beneficio por unidad',x=>moneyIn(x.profit,x.currency)],['Margen real',x=>(Number(x.margin)||0).toFixed(2)+' %'],['Notas',x=>normalizeHistoryNote(x.jobNotes||x.notes||'—')]];panel.classList.remove('hidden');panel.innerHTML='<strong>Comparativa de tasaciones</strong><div style="overflow-x:auto"><table class="history"><thead><tr><th>Dato</th><th>'+escapeHtml(chosen[0].name||'Tasación A')+'</th><th>'+escapeHtml(chosen[1].name||'Tasación B')+'</th></tr></thead><tbody>'+fields.map(([label,get])=>'<tr><td>'+escapeHtml(label)+'</td><td>'+escapeHtml(get(chosen[0]))+'</td><td>'+escapeHtml(get(chosen[1]))+'</td></tr>').join('')+'</tbody></table></div>';}
$('historySearch')?.addEventListener('input',renderHistory);$('historySort')?.addEventListener('change',renderHistory);$('historyCompareBtn')?.addEventListener('click',renderHistoryComparison);$('historyCompareClearBtn')?.addEventListener('click',()=>{historyCompareSelection=[];renderHistory();$('historyCompare').classList.add('hidden');toast('Selección de comparativa limpiada.');});
function loadHistory(i){const x=getHistory()[i];if(!x)return;if(x.currency&&$('currency'))$('currency').value=x.currency;if(x.taxCountry&&$('taxCountry'))$('taxCountry').value=x.taxCountry;if(x.taxRate!==undefined&&$('taxRate'))$('taxRate').value=x.taxRate;updateCurrencyLabels();$('profileName').value=x.profile||'';if($('accountingType'))$('accountingType').value=x.accountingType||'personal';if($('accountingClient'))$('accountingClient').value=x.accountingClient||'';$('jobNotes').value=x.jobNotes||x.notes||'';$('pieceName').value=x.name;showPieceImage(x.image||'');$('printHours').value=x.hours;$('qty').value=x.qty;$('salePrice').value=x.taxMode==='inclusive'?((x.grossSale??x.sale)/(1+((x.taxRate||0)/100))): (x.enteredSale!==undefined?x.enteredSale:x.sale);$('filamentRows').innerHTML='';x.filaments.forEach(f=>addFilament(f.name,f.grams,f.price,f.color,f.spoolIndex??''));calculate();toast('Cálculo cargado.');}
async function exportJSON(){let appVersion='desconocida';try{const response=await fetch('/api/version',{cache:'no-store'});if(response.ok){const versionData=await response.json();if(versionData&&versionData.ok&&typeof versionData.version==='string'&&/^\\d+\\.\\d+(?:\\.\\d+)?$/.test(versionData.version))appVersion=versionData.version;}}catch(e){}const payload={app:'Print Cost & Profit',version:appVersion,exportedAt:new Date().toISOString(),history:getHistory(),settings:readSettings(),draft:draftData()};download(new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'}),'Print_Cost_Profit_copia.json');toast(appVersion==='desconocida'?'Copia JSON descargada. No se pudo consultar la versión central del servidor.':'Copia JSON descargada: incluye historial, ajustes y cálculo actual.');}
function readSettings(){const cfg={};['electricity','watts','maintenanceHour','wear','postMinutes','hourlyLabor','assemblyMinutes','finishCost','labor','packing','extra','failurePct','commission','fixedCommission','targetMargin','targetProfit','priceRounding','currency','taxCountry','taxRate'].forEach(id=>{if($(id))cfg[id]=$(id).value});cfg.taxEnabled=$('taxEnabled')?$('taxEnabled').checked:true;return cfg;}
async function importJSON(file){try{const data=JSON.parse(await readFileText(file));if(!data||!Array.isArray(data.history))throw new Error('Formato');if(!(await window.PCPConfirm('La restauración sustituirá el historial local actual y, si la copia contiene uno, el cálculo en curso. ¿Continuar?')))return;const clean=data.history.filter(x=>x&&typeof x.name==='string'&&Array.isArray(x.filaments)).slice(0,100);setHistory(clean);if(data.settings&&typeof data.settings==='object'){Object.entries(data.settings).forEach(([id,v])=>{if(['electricity','watts','maintenanceHour','postMinutes','hourlyLabor','assemblyMinutes','finishCost','labor','packing','extra','failurePct','commission','targetMargin','targetProfit','priceRounding','currency','taxCountry','taxRate','taxEnabled'].includes(id)&&$(id)){if(id==='taxEnabled')$(id).checked=!!v;else $(id).value=v};});}try{localStorage.setItem('pcp_settings',JSON.stringify(data.settings||{}));}catch(e){}if(data.draft&&Array.isArray(data.draft.filaments)&&data.draft.filaments.length){const d=data.draft;['pieceName','profileName','jobNotes','printHours','qty','failurePct','electricity','watts','maintenanceHour','postMinutes','hourlyLabor','assemblyMinutes','finishCost','labor','packing','extra','salePrice','commission','fixedCommission','targetMargin','targetProfit','currency','taxCountry','taxRate','taxEnabled','comparePrice1','comparePrice2','comparePrice3','priceRounding'].forEach(id=>{if(d[id]!==undefined&&$(id)){if(id==='taxEnabled')$(id).checked=!!d[id];else $(id).value=d[id]}});$('filamentRows').innerHTML='';d.filaments.forEach(f=>addFilament(f.name,f.grams,f.price,f.color,f.spoolIndex??''));showPieceImage(d.pieceImage||'');currentFile=d.currentFile||'';resultCalculated=!!d.resultCalculated;updateCurrencyLabels();saveDraft();calculate();}updateCurrencyLabels();toast(data.draft?'Copia restaurada: historial, ajustes y cálculo actual.':'Copia restaurada. Este archivo antiguo no incluía el cálculo actual.');}catch(e){console.error('Error al restaurar copia JSON',e);alert('No se pudo restaurar: el archivo no parece una copia válida de Print Cost & Profit.');}}
function exportCSV(){const h=getHistory();if(!h.length){toast('No hay historial que exportar.');return}const rows=[['Fecha','Pieza','Perfil','Notas','Archivo','Tiempo horas','Unidades','Gramos','Moneda','Impuesto %','Precio sin impuesto','Impuesto/unidad','Precio final con impuesto','Coste unidad','Beneficio unidad','Beneficio total','Margen %','Precio recomendado con impuesto'],...h.map(x=>[x.date,x.name,x.profile||'',x.jobNotes||x.notes||'',x.file||'',x.hours,x.qty,x.grams,x.currency||'EUR',x.taxRate??0,x.netSale??x.sale,x.taxPerUnit??0,x.grossSale??x.sale,x.cost,x.profit,x.totalProfit,x.margin,x.suggested])];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');download(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),'Print_Cost_Profit_historial.csv');}

function exportQuoteCSV(){const r=calculate();const rows=[['Presupuesto Print Cost & Profit'],['Fecha',new Date().toLocaleString((window.PCP_LOCALE||'es-ES'))],['Pieza',$('pieceName').value],['Perfil',$('profileName').value],['Notas',$('jobNotes').value],['Archivo G-code',currentFile||''],['Tiempo de impresión (h)',$('printHours').value],['Unidades',$('qty').value],['Reserva fallos (%)',$('failurePct').value],['Material','Gramos','Precio '+r.currency+'/kg','Coste material '+r.currency],...r.filaments.map(f=>[f.name+' · '+(f.colorName||namedColor(f.color))+' '+(f.color||''),f.grams,f.price,(Math.max(0,Number(f.grams)||0)*Math.max(0,Number(f.price)||0)/1000).toFixed(4)]),['Coste filamento/u. €',r.filament],['Electricidad/u. '+r.currency,r.electricity],['Desgaste/u. '+r.currency,r.wear],['Otros costes/u. '+r.currency,r.other],['Reserva fallos/u. '+r.currency,r.fail],['Moneda',r.currency],['Perfil fiscal',r.taxCountry],['Impuesto (%)',r.taxRate*100],['Modo precio',r.taxMode],['Comisión (%)',Number($('commission').value)||0],['Comisión fija por venta',Number($('fixedCommission')?.value)||0],['Coste total/u. '+r.currency,r.unitCost],['Precio sin impuestos/u. '+r.currency,r.sale],['Impuesto/u. '+r.currency,r.taxPerUnit],['Impuestos totales pedido '+r.currency,r.taxTotal],['Precio con impuestos/u. '+r.currency,r.grossSale],['Beneficio/u. '+r.currency,r.profit],['Beneficio total pedido '+r.currency,r.profit*r.qty],['Margen sobre venta (%)',r.realMargin],['Rentabilidad sobre coste (%)',r.returnOnCost],['Precio recomendado con impuestos/u. '+r.currency,r.suggested]];const csv=rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');const safe=($('pieceName').value||'pieza').replace(/[^a-z0-9_-]+/gi,'_').slice(0,50)||'pieza';download(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),'Presupuesto_'+safe+'.csv');toast('Presupuesto individual exportado a CSV.');}
function buildSummary(){const r=calculate();return ['PRESUPUESTO · PRINT COST & PROFIT','Pieza: '+($('pieceName').value||'Sin nombre'),'Perfil: '+($('profileName').value||'Sin perfil'),'Tiempo: '+$('printHours').value+' h','Unidades: '+r.qty,'Moneda: '+r.currency,'Impuesto: '+pct(r.taxRate*100)+' ('+r.taxCountry+')','Precio sin impuestos por unidad: '+money(r.sale),'Impuesto por unidad: '+money(r.taxPerUnit),'Precio con impuestos por unidad: '+money(r.grossSale),'Coste por unidad: '+money(r.unitCost),'Beneficio por unidad: '+money(r.profit),'Beneficio total del pedido: '+money(r.profit*r.qty),'Margen sobre venta: '+pct(r.realMargin),'Rentabilidad sobre coste: '+pct(r.returnOnCost),'Precio recomendado con impuestos: '+money(r.suggested),'Materiales: '+r.filaments.map(f=>f.name+' '+f.grams+' g a '+money(f.price)+'/kg').join(' | ')].join('\n');}
async function copySummary(){const text=buildSummary();try{if(navigator.clipboard&&navigator.clipboard.writeText){await navigator.clipboard.writeText(text);toast('Resumen copiado al portapapeles.');return}}catch(e){}const ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();let ok=false;try{ok=document.execCommand('copy')}catch(e){}ta.remove();if(ok)toast('Resumen copiado al portapapeles.');else{const blob=new Blob([text],{type:'text/plain;charset=utf-8'});download(blob,'Resumen_presupuesto.txt');toast('El navegador no permitió copiarlo; se ha descargado el resumen en TXT.')}}

function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}


function calculateFailureExpectation(){const r=calculate();const p=Math.min(99,Math.max(0,Number($('failureRateSim').value)||0))/100;const retry=Math.max(0,Number($('failureLaborSim').value)||0);const attempts=p>=1?Infinity:1/(1-p);const expected=Number.isFinite(attempts)?(r.unitCost+retry)*attempts:Infinity;$('failureSimResult').innerHTML='Probabilidad de fallo: '+pct(p*100)+'<br>Intentos medios estimados: '+(Number.isFinite(attempts)?attempts.toFixed(2).replace('.',','):'no calculable')+'<br><strong>Coste esperado por pieza vendible: '+(Number.isFinite(expected)?money(expected):'no calculable')+'</strong><br><span class="section-note">Modelo estadístico orientativo: supone que cada intento es independiente y que un fallo obliga a repetir toda la pieza.</span>'; }

function printCustomerQuote(autoPrint=true,savedQuote=null){
  const r=calculate(),val=id=>$(id)?.value?.trim()||'',q=savedQuote;
  const client=fullClientRecord(q?.client||{name:val('clientName'),email:val('clientEmail'),phone:val('clientPhone'),address:val('clientAddress')});
  const sd=q?.seller||sellerData();
  const seller={company:sd.company||sd.quoteCompany||val('quoteCompany'),address:sd.address||sd.quoteSellerAddress||val('quoteSellerAddress'),quoteSellerPostalCode:sd.quoteSellerPostalCode||val('quoteSellerPostalCode'),quoteSellerCity:sd.quoteSellerCity||val('quoteSellerCity'),quoteSellerProvince:sd.quoteSellerProvince||val('quoteSellerProvince'),taxId:sd.taxId||sd.quoteTaxId||val('quoteTaxId'),email:sd.email||sd.quoteSellerEmail||val('quoteSellerEmail'),phone:sd.phone||sd.quoteSellerPhone||val('quoteSellerPhone')};
  const items=(Array.isArray(q?.items)&&q.items.length?q.items:quoteLineRows().length?quoteLineRows():[{description:val('pieceName')||'Pieza 3D',qty:Math.max(1,Math.floor(Number($('qty').value)||1)),unitPrice:r.sale}]).map(x=>({description:x.description||'Pieza 3D',qty:Math.max(1,Number(x.qty)||1),unitPrice:Math.max(0,Number(x.unitPrice)||0)}));
  const subtotal=items.reduce((sum,x)=>sum+x.qty*x.unitPrice,0),discountPct=q?Math.max(0,Math.min(100,Number(q.discountPct)||0)):Math.max(0,Math.min(100,Number($('quoteDiscount')?.value)||0));
  const discount=q?Number(q.discount??subtotal*discountPct/100):subtotal*discountPct/100,shipping=Math.max(0,Number(q?.shipping??$('quoteShipping')?.value)||0);
  const base=q?Number(q.base??Math.max(0,subtotal-discount)+shipping):Math.max(0,subtotal-discount)+shipping,rate=q?Number(q.taxRate)||0:r.taxRate||0,tax=q?Number(q.tax??base*rate):base*rate,total=q?Number(q.total??base+tax):base+tax;
  const doc={quoteNumber:q?.quoteNumber||'',date:q?.date||new Date().toISOString(),seller,client,items,product:items[0]?.description||'Pieza 3D',qty:items[0]?.qty||1,unitPrice:items[0]?.unitPrice||0,discount,discountPct,shipping,base,taxRate:rate,tax,total,validity:q?.validity||val('quoteValidity')||'15 días',delivery:q?.delivery||val('quoteDelivery')||'A confirmar',currency:q?.currency||currency()};
  const blob=pcpMakePdf('presupuesto',doc),url=URL.createObjectURL(blob),win=window.open(url,'_blank');
  if(!win){URL.revokeObjectURL(url);alert('El navegador bloqueó la ventana del presupuesto. Permite las ventanas emergentes para este archivo.');return;}
  if(autoPrint){const tryPrint=()=>{try{win.focus();win.print();}catch(e){}};win.addEventListener('load',()=>setTimeout(tryPrint,500),{once:true});}
}
function refreshDashboard(){const hist=getHistory();const month=new Date().toISOString().slice(0,7);const current=hist.filter(x=>String(x.date||'').slice(0,7)===month);const totalUnits=current.reduce((s,x)=>s+(Number(x.qty)||0),0);const revenue=current.reduce((s,x)=>s+(Number(x.sale)||0)*(Number(x.qty)||0),0);const profit=current.reduce((s,x)=>s+(Number(x.totalProfit)||((Number(x.profit)||0)*(Number(x.qty)||0))),0);const costs=current.reduce((s,x)=>s+(Number(x.cost)||0)*(Number(x.qty)||0),0);const top=[...hist].sort((a,b)=>(Number(b.profit)||0)-(Number(a.profit)||0))[0];$('dashboardResult').innerHTML='<strong>Mes actual: '+month+'</strong><br>Cálculos guardados este mes: '+current.length+'<br>Unidades registradas: '+totalUnits+'<br>Ingresos estimados registrados: '+money(revenue)+'<br>Costes estimados: '+money(costs)+'<br>Beneficio estimado: '+money(profit)+'<br>Mejor beneficio unitario del historial: '+(top?escapeHtml(top.name)+' ('+money(Number(top.profit)||0)+')':'sin datos')+'<br><span class="section-note">Solo se cuentan los cálculos guardados; no se detectan automáticamente ventas reales ni cobros.</span>'; }
$('dashboardRefreshBtn').addEventListener('click',refreshDashboard);
// Datos del vendedor y agenda local de clientes
const sellerFields=['quoteCompany','quoteSellerEmail','quoteSellerPhone','quoteSellerAddress','quoteSellerPostalCode','quoteSellerCity','quoteSellerProvince','quoteTaxId'];
function getSavedClients(){try{return JSON.parse(localStorage.getItem('pcp_clients')||'[]')}catch(e){return []}}
function fullClientRecord(clientOrName){const base=typeof clientOrName==='string'?{name:clientOrName}:({...clientOrName||{}});const clients=getSavedClients();const key=String(base.name||'').trim().toLocaleLowerCase('es');const match=clients.find(c=>String(c.name||'').trim().toLocaleLowerCase('es')===key)||(base.email?clients.find(c=>String(c.email||'').trim().toLowerCase()===String(base.email).trim().toLowerCase()):null);return {...(match||{}),...base,...Object.fromEntries(['name','email','phone','address','postalCode','city','province','taxId','notes'].map(k=>[k,base[k]||match?.[k]||'']))}}
function clientAddressLines(c){const x=fullClientRecord(c);return [x.address,[x.postalCode,x.city].filter(Boolean).join(' '),x.province,x.taxId?'NIF/DNI: '+x.taxId:'',x.email?'Email: '+x.email:'',x.phone?'Teléfono: '+x.phone:'',x.notes?'Observaciones: '+x.notes:''].filter(Boolean)}
function sellerData(){return Object.fromEntries(sellerFields.map(id=>[id,$(id)?.value?.trim()||'']))}
function invoiceSellerData(){let saved={};try{saved=JSON.parse(localStorage.getItem('pcp_seller')||'{}')||{}}catch(e){}const read=id=>(($(id)?.value||'').trim()||String(saved[id]||'').trim());return {company:read('quoteCompany'),email:read('quoteSellerEmail'),phone:read('quoteSellerPhone'),address:read('quoteSellerAddress'),taxId:read('quoteTaxId')}}
function loadSellerData(){try{const d=JSON.parse(localStorage.getItem('pcp_seller')||'null');if(d)sellerFields.forEach(id=>{const el=$(id);if(el&&d[id]!==undefined)el.value=d[id]});const st=$('sellerSettingsStatus');if(st)st.textContent=d?'Datos del vendedor guardados en la base de datos SQLite de este PC.':'Configura y guarda tus datos para reutilizarlos.'}catch(e){}}
function saveSellerData(){const ok=STORE.set('pcp_seller',JSON.stringify(sellerData()));if(ok){$('sellerSettingsStatus').textContent='Datos del vendedor guardados. Se reutilizarán en presupuestos y documentos imprimibles.';toast('Datos del vendedor guardados en la base de datos SQLite de este PC.')}}
