function nextAnnualQuoteNumber(dateValue){const d=dateValue?new Date(dateValue):new Date();const year=String(d.getFullYear());let max=0;for(const q of getSavedQuotes()){let n=String(q.quoteNumber||'');const m=n.match(/^(\d{4})-(\d+)$/);if(m&&m[1]===year)max=Math.max(max,Number(m[2])||0);else if(!n&&q.date&&new Date(q.date).getFullYear()===d.getFullYear()){const legacy=String(q.id||'').match(/^(\d{4})-(\d+)$/);if(legacy)max=Math.max(max,Number(legacy[2])||0);}}return year+'-'+(max+1)}
