function quoteLineRows(){return [...document.querySelectorAll('#quoteLinesEditor .quote-line-row')].map(row=>({description:row.querySelector('[data-line-description]')?.value.trim()||'Pieza 3D',qty:Math.max(1,Math.floor(Number(row.querySelector('[data-line-qty]')?.value)||1)),unitPrice:Math.max(0,Number(row.querySelector('[data-line-price]')?.value)||0)})).filter(x=>x.description);}
function renderQuoteLineEditor(lines){const el=$('quoteLinesEditor');if(!el)return;const rows=Array.isArray(lines)?lines:quoteLineRows();el.innerHTML='';rows.forEach((line,i)=>{const row=document.createElement('div');row.className='quote-line-row';row.style.cssText='display:grid;grid-template-columns:minmax(180px,2fr) minmax(80px,.55fr) minmax(110px,.8fr) auto;gap:8px;align-items:center';row.innerHTML='<input data-line-description aria-label="Descripción de la pieza" placeholder="Nombre o descripción de la pieza"><input data-line-qty aria-label="Cantidad" type="number" min="1" step="1" value="1"><input data-line-price aria-label="Precio unitario" type="number" min="0" step="0.01" value="0"><button type="button" class="btn history-delete" data-line-remove aria-label="Eliminar pieza">Eliminar</button>';row.querySelector('[data-line-description]').value=line.description||'';row.querySelector('[data-line-qty]').value=Math.max(1,Number(line.qty)||1);row.querySelector('[data-line-price]').value=Math.max(0,Number(line.unitPrice)||0);row.querySelectorAll('input').forEach(inp=>inp.addEventListener('input',updateQuoteLineTotals));row.querySelector('[data-line-remove]').addEventListener('click',()=>{row.remove();updateQuoteLineTotals()});el.appendChild(row)});updateQuoteLineTotals();}
function updateQuoteLineTotals(){const lines=quoteLineRows();const subtotal=lines.reduce((s,x)=>s+x.qty*x.unitPrice,0);const ship=Math.max(0,Number($('quoteShipping')?.value)||0);const discountPct=Math.max(0,Math.min(100,Number($('quoteDiscount')?.value)||0));const discount=subtotal*discountPct/100;const el=$('quoteLinesTotal');if(el)el.textContent='Subtotal: '+money(subtotal)+' · Descuento ('+pct(discountPct)+'): −'+money(discount)+' · Envío: '+money(ship)+' · Base: '+money(Math.max(0,subtotal-discount)+ship);}
function addQuoteLine(description,qty,unitPrice){const lines=quoteLineRows();lines.push({description:description||'',qty:qty||1,unitPrice:unitPrice||0});renderQuoteLineEditor(lines);}
