async function pcpShareDocument(channel,kind,doc){
  try{
    const client=doc.client||{},isInvoice=kind==='factura',data=pcpShareMessage(channel,kind,doc);
    const cleanNum=isInvoice?(doc.number||'factura'):(doc.quoteNumber||'presupuesto');
    const file=new File([pcpMakePdf(kind,doc)],(isInvoice?'Factura_':'Presupuesto_')+String(cleanNum).replace(/[^a-zA-Z0-9_-]/g,'_')+'.pdf',{type:'application/pdf'});
    let phone=String(client.phone||client.telefono||client.mobile||client.movil||'').trim();
    let email=String(client.email||client.correo||client.mail||'').trim();
    let destination='';
    if(channel==='whatsapp'){
      phone=phone.replace(/[^\d+]/g,'');
      if(phone.startsWith('00'))phone='+'+phone.slice(2);
      if(phone.startsWith('+'))phone=phone.slice(1);
      if(/^[6789]\d{8}$/.test(phone))phone='34'+phone;
      if(!phone||phone.length<9){alert('El cliente no tiene un teléfono válido guardado. Revisa el teléfono en la pestaña Clientes e incluye el prefijo internacional si no es de España.');return;}
      destination='https://wa.me/'+phone+'?text='+encodeURIComponent(data.message);
    }else{
      email=email.replace(/^mailto:/i,'').trim();
      if(!email||! /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){alert('El cliente no tiene una dirección de correo válida guardada. Revisa el email en la pestaña Clientes.');return;}
      destination='mailto:'+email+'?subject='+encodeURIComponent(data.title)+'&body='+encodeURIComponent(data.message);
    }
    // No descargar automáticamente: el usuario decide en el aviso cuándo guardar el PDF.
    pcpShowPdfDownloadNotice(channel,destination,file);
  }catch(err){console.error('Error al preparar documento para compartir',err);alert('No se ha podido generar el PDF. Comprueba los datos del documento e inténtalo de nuevo.');}
}
function pcpShowPdfDownloadNotice(channel,destination,file){
  const old=document.getElementById('pcpPdfNoticeOverlay');if(old)old.remove();
  const overlay=document.createElement('div');overlay.id='pcpPdfNoticeOverlay';
  overlay.style.cssText='position:fixed;inset:0;z-index:99999;background:rgba(3,8,18,.82);display:flex;align-items:center;justify-content:center;padding:18px;font-family:Segoe UI,Arial,sans-serif;';
  const isWhatsApp=channel==='whatsapp';
  const title=isWhatsApp?'Antes de enviar por WhatsApp':'Antes de enviar por correo';
  const next=isWhatsApp?'Continuar a WhatsApp':'Continuar al correo';
  const safeName=file.name.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  overlay.innerHTML='<div role="dialog" aria-modal="true" aria-labelledby="pcpPdfNoticeTitle" style="width:min(520px,100%);background:#131b2e;color:#eef4ff;border:1px solid #3b526e;border-radius:16px;padding:26px;box-shadow:0 20px 70px #0009"><div style="font-size:34px;margin-bottom:8px">📎</div><h2 id="pcpPdfNoticeTitle" style="margin:0 0 12px;font-size:21px">'+title+'</h2><p style="color:#d4deef;line-height:1.55;margin:0 0 10px">Recuerda descargar <strong style="overflow-wrap:anywhere">'+safeName+'</strong> antes de continuar.</p><p style="color:#d4deef;line-height:1.55;margin:0 0 20px">Después, cuando se abra el destinatario, adjunta el PDF manualmente al mensaje. El documento todavía no se ha descargado.</p><div style="display:flex;gap:10px;justify-content:flex-end;flex-wrap:wrap"><button type="button" id="pcpPdfNoticeClose" style="cursor:pointer;background:#23314a;color:#eef4ff;border:1px solid #405574;border-radius:9px;padding:11px 15px;font-weight:600">Cerrar</button><button type="button" id="pcpPdfNoticeDownload" style="cursor:pointer;background:#23314a;color:#eef4ff;border:1px solid #405574;border-radius:9px;padding:11px 15px;font-weight:700">Descargar PDF</button><button type="button" id="pcpPdfNoticeContinue" style="cursor:pointer;background:#65d6c4;color:#071a1b;border:1px solid #65d6c4;border-radius:9px;padding:11px 15px;font-weight:700">'+next+'</button></div></div>';
  document.body.appendChild(overlay);
  const close=()=>overlay.remove();
  overlay.querySelector('#pcpPdfNoticeClose').addEventListener('click',close);
  overlay.addEventListener('click',e=>{if(e.target===overlay)close();});
  overlay.querySelector('#pcpPdfNoticeDownload').addEventListener('click',()=>{
    const blobUrl=URL.createObjectURL(file),a=document.createElement('a');
    a.href=blobUrl;a.download=file.name;a.style.display='none';document.body.appendChild(a);a.click();a.remove();
    setTimeout(()=>URL.revokeObjectURL(blobUrl),60000);
    const b=overlay.querySelector('#pcpPdfNoticeDownload');b.textContent='PDF descargado';b.disabled=true;b.style.opacity='.7';
  });
  overlay.querySelector('#pcpPdfNoticeContinue').addEventListener('click',()=>{
    if(channel==='whatsapp'){
      // Abrir WhatsApp directamente desde el clic del usuario, sin abrir ventanas intermedias ni PDFs.
      const w=window.open(destination,'_blank','noopener,noreferrer');
      if(!w){ window.location.assign(destination); }
    }else{
      // mailto abre el cliente de correo predeterminado; no se genera ni abre ninguna pestaña PDF.
      window.location.href=destination;
    }
    close();
  });
}
