function getSpools(){try{return JSON.parse(localStorage.getItem('pcp_spools')||'[]')}catch(e){return []}}
let spoolMaterialFilter='all';
function spoolMaterialKey(v){return String(v||'Material sin indicar').trim().replace(/\s+/g,' ').toLocaleLowerCase('es');}
function spoolFilterMatch(s){return spoolMaterialFilter==='all'||spoolMaterialKey(s.material)===spoolMaterialFilter}

