function renderSpoolMaterialFilters(all){const wrap=$('spoolMaterialFilters');if(!wrap)return;const materials=[...new Map(all.map(s=>{const label=String(s.material||'Material sin indicar').trim()||'Material sin indicar';return [spoolMaterialKey(label),label]})).entries()].sort((a,b)=>a[1].localeCompare(b[1],'es',{sensitivity:'base'}));if(spoolMaterialFilter!=='all'&&!materials.some(([key])=>key===spoolMaterialFilter))spoolMaterialFilter='all';wrap.innerHTML='<button type="button" class="btn" data-spool-filter="all">Todas</button>'+materials.map(([key,label])=>'<button type="button" class="btn" data-spool-filter="'+escapeHtml(key)+'">'+escapeHtml(label)+'</button>').join('');wrap.querySelectorAll('[data-spool-filter]').forEach(b=>{const active=b.dataset.spoolFilter===spoolMaterialFilter;b.classList.toggle('primary',active);b.setAttribute('aria-pressed',active?'true':'false');b.addEventListener('click',()=>{spoolMaterialFilter=b.dataset.spoolFilter;renderSpools()})})}
function pcpPaginateCards(container,selector,pageKey,totalRows){const old=container.querySelector('[data-pcp-pager="'+pageKey+'"]');if(old)old.remove();const all=Array.from(container.querySelectorAll(selector));const query=String($('spoolsSearch')?.value||'').trim().toLocaleLowerCase();const rows=all.filter(card=>!query||card.textContent.toLocaleLowerCase().includes(query));all.forEach(card=>card.style.display='none');if(!rows.length)return;const pages=Math.max(1,Math.ceil(rows.length/PCP_LIST_PAGE_SIZE));PCP_LIST_PAGES[pageKey]=Math.min(Math.max(1,PCP_LIST_PAGES[pageKey]||1),pages);const nav=document.createElement('div');nav.dataset.pcpPager=pageKey;nav.className='list-pagination';const prev=document.createElement('button');prev.type='button';prev.className='btn';const label=document.createElement('span');const next=document.createElement('button');next.type='button';next.className='btn';const lang=(window.PCP_LANG||document.documentElement.lang||'es').slice(0,2);const w={es:['Anterior','Página','Siguiente','bobinas'],en:['Previous','Page','Next','spools'],fr:['Précédent','Page','Suivant','bobines'],de:['Zurück','Seite','Weiter','Spulen'],it:['Precedente','Pagina','Successivo','bobine'],pl:['Poprzednia','Strona','Następna','szpul']}[lang]||['Anterior','Página','Siguiente','bobinas'];const draw=()=>{const pg=PCP_LIST_PAGES[pageKey];rows.forEach((r,i)=>r.style.display=(i>=(pg-1)*PCP_LIST_PAGE_SIZE&&i<pg*PCP_LIST_PAGE_SIZE)?'':'none');prev.textContent=w[0];next.textContent=w[2];prev.disabled=pg===1;next.disabled=pg===pages;label.textContent=w[1]+' '+pg+' / '+pages+' · '+rows.length+' '+w[3]};prev.onclick=()=>{if(PCP_LIST_PAGES[pageKey]>1){PCP_LIST_PAGES[pageKey]--;draw()}};next.onclick=()=>{if(PCP_LIST_PAGES[pageKey]<pages){PCP_LIST_PAGES[pageKey]++;draw()}};nav.append(prev,label,next);container.appendChild(nav);draw();}
const spoolSortExtra=$('spoolsSort');if(spoolSortExtra&&!spoolSortExtra.dataset.bound){spoolSortExtra.addEventListener('change',()=>{const native=$('spoolSortOrder');const map={'0':'default','1':'color','2':'default','3':'quantity-desc'};if(native)native.value=map[spoolSortExtra.value]||'default';localStorage.setItem('pcp_spool_sort_order',map[spoolSortExtra.value]||'default');PCP_LIST_PAGES.spools=1;renderSpools()});spoolSortExtra.dataset.bound='1';}
function renderSpools(){const all=getSpools(),el=$('spoolsList');renderSpoolMaterialFilters(all);el.classList.add('spools-inventory');const spoolQuery=String($('spoolsSearch')?.value||'').trim().toLocaleLowerCase();const a=all.map((s,i)=>({...s,_index:i,quantity:Math.max(1,Math.floor(Number(s.quantity)||1))})).filter(spoolFilterMatch).filter(s=>!spoolQuery||[s.material,s.colorName,s.color,s.brand,s.hex].some(v=>String(v||'').toLocaleLowerCase().includes(spoolQuery))).sort((x,y)=>{const mode=(document.getElementById('spoolSortOrder')||{}).value||localStorage.getItem('pcp_spool_sort_order')||'default';if(mode==='color')return String(x.colorName||x.color||'').localeCompare(String(y.colorName||y.color||''),'es',{sensitivity:'base'})||String(x.material||'').localeCompare(String(y.material||''),'es',{sensitivity:'base'})||String(x.brand||'').localeCompare(String(y.brand||''),'es',{sensitivity:'base'});if(mode==='quantity-desc')return y.quantity-x.quantity||String(x.material||'').localeCompare(String(y.material||''),'es',{sensitivity:'base'})||String(x.colorName||x.color||'').localeCompare(String(y.colorName||y.color||''),'es',{sensitivity:'base'});if(mode==='quantity-asc')return x.quantity-y.quantity||String(x.material||'').localeCompare(String(y.material||''),'es',{sensitivity:'base'})||String(x.colorName||x.color||'').localeCompare(String(y.colorName||y.color||''),'es',{sensitivity:'base'});return String(x.material||'').localeCompare(String(y.material||''),'es',{sensitivity:'base'})||String(x.colorName||x.color||'').localeCompare(String(y.colorName||y.color||''),'es',{sensitivity:'base'})||String(x.brand||'').localeCompare(String(y.brand||''),'es',{sensitivity:'base'});});const totalCount=all.reduce((n,s)=>n+Math.max(1,Math.floor(Number(s.quantity)||1)),0);const summary=$('spoolInventorySummary');if(summary)summary.textContent='Inventario: '+totalCount+' bobina(s) en total · '+a.reduce((n,s)=>n+s.quantity,0)+' bobina(s) en este filtro.';if(!a.length){el.innerHTML='<div class="spools-empty"><span class="spools-empty-icon">◉</span><strong>No hay bobinas en esta categoría</strong><span>Prueba otra pestaña o añade una bobina.</span></div>';return}el.innerHTML='<div class="spool-cards">'+a.map(s=>{const i=s._index,initial=Math.max(0,Number(s.initial)||0),remaining=Math.min(initial,Math.max(0,Number(s.remaining)||0)),pct=initial>0?Math.round(remaining/initial*100):0,hex=/^#[0-9a-f]{6}$/i.test(s.hex||'')?s.hex:'#808080',kg=initial>0?(Number(s.price)||0)*1000/initial:0;return '<article class="spool-card"><div class="spool-card-top"><span class="spool-swatch" style="--spool-color:'+hex+';background:'+hex+'"></span><div class="spool-ident"><div class="spool-material">'+escapeHtml(s.material||'Material sin indicar')+' <span class="spool-slash">/</span> '+escapeHtml(s.colorName||s.color||'Sin color')+'</div><div class="spool-brand">'+escapeHtml(s.brand||'Marca no indicada')+'</div></div><span class="spool-percent">'+s.quantity+' '+(Number(s.quantity)===1?(window.PCP_I18N?.t('bobina')||'bobina'):(window.PCP_I18N?.t('bobinas')||'bobinas'))+'</span></div><div class="spool-progress"><span style="width:'+pct+'%;background:'+hex+'"></span></div><div class="spool-stats"><div class="spool-stat spool-remaining"><span>Restante por bobina</span><label><input type="number" min="0" max="'+initial+'" step="1" value="'+remaining+'" data-spool-remaining="'+i+'"> <small>g</small></label></div><div class="spool-stat"><span>Inicial por bobina</span><strong>'+initial.toLocaleString((window.PCP_LOCALE||'es-ES'))+' g</strong></div><div class="spool-stat spool-cost"><span>Precio estimado/kg</span><strong>'+money(kg)+'</strong></div></div><div class="spool-card-actions"><button class="btn" data-spool-edit="'+i+'">✎ Editar</button><button class="btn spool-delete" data-spool-delete="'+i+'">Borrar</button></div></article>'}).join('')+'</div>';pcpPaginateCards(el,'.spool-card','spools',a.length);el.querySelectorAll('[data-spool-remaining]').forEach(x=>x.addEventListener('change',()=>{const z=getSpools(),idx=Number(x.dataset.spoolRemaining);z[idx].remaining=Math.min(Number(z[idx].initial)||0,Math.max(0,Number(x.value)||0));STORE.set('pcp_spools',JSON.stringify(z));renderSpools()}));el.querySelectorAll('[data-spool-edit]').forEach(x=>x.addEventListener('click',()=>{const z=getSpools()[Number(x.dataset.spoolEdit)];if(!z)return;$('spoolMaterial').value=z.material;$('spoolBrand').value=[...$('spoolBrand').options].some(o=>o.value===(z.brand||''))?(z.brand||'Generic'):'__custom__';$('spoolBrandCustom').classList.toggle('hidden',$('spoolBrand').value!=='__custom__');$('spoolBrandCustom').value=$('spoolBrand').value==='__custom__'?(z.brand||''):'';$('spoolColor').value=z.colorName||z.color;$('spoolColorPicker').value=/^#[0-9a-f]{6}$/i.test(z.hex||'')?z.hex:'#000000';$('spoolColor').value=window.PCP_I18N?.colorDisplay($('spoolColor').value)||$('spoolColor').value;updateSpoolColorLabel(false);$('spoolInitial').value=z.initial;$('spoolRemaining').value=z.remaining;$('spoolQuantity').value=Math.max(1,Math.floor(Number(z.quantity)||1));$('spoolPrice').value=z.price;editingSpool=Number(x.dataset.spoolEdit);$('addSpoolBtn').textContent='Guardar cambios';$('spoolMaterial').scrollIntoView({behavior:'smooth',block:'center'})}));el.querySelectorAll('[data-spool-delete]').forEach(x=>x.addEventListener('click',async ()=>{if(!(await window.PCPConfirm('¿Borrar este registro de bobinas del inventario?')))return;const z=getSpools();z.splice(Number(x.dataset.spoolDelete),1);STORE.set('pcp_spools',JSON.stringify(z));renderSpools()}))}

window.PCPRefreshSpools=function(){try{renderSpools();return true}catch(e){console.error('No se pudo actualizar el inventario de bobinas',e);return false;}};
