$('addSpoolBtn').addEventListener('click',()=>{const initial=Math.max(0,Number($('spoolInitial').value)||0),remaining=Math.min(initial,Math.max(0,Number($('spoolRemaining').value)||0));const a=getSpools(),item={material:$('spoolMaterial').value==='Otro'?($('spoolMaterialCustom')?.value.trim()||'Otro'):$('spoolMaterial').value,brand:$('spoolBrand').value==='__custom__'?($('spoolBrandCustom').value.trim()||'Personalizada'):$('spoolBrand').value,color:window.PCP_I18N?.colorSource($('spoolColor').value.trim()||namedColor($('spoolColorPicker').value))||$('spoolColor').value.trim()||namedColor($('spoolColorPicker').value),colorName:window.PCP_I18N?.colorSource($('spoolColor').value.trim()||namedColor($('spoolColorPicker').value))||$('spoolColor').value.trim()||namedColor($('spoolColorPicker').value),hex:$('spoolColorPicker').value,initial,remaining,quantity:Math.max(1,Math.floor(Number($('spoolQuantity').value)||1)),price:Math.max(0,Number($('spoolPrice').value)||0)};const wasEditing=editingSpool>=0;if(wasEditing){a[editingSpool]=item;editingSpool=-1;$('addSpoolBtn').textContent='Añadir bobina'}else a.push(item);if(STORE.set('pcp_spools',JSON.stringify(a))){renderSpools();toast(wasEditing?'Bobina actualizada.':'Bobina añadida.')}});$('exportSpoolsBtn').addEventListener('click',()=>{const a=getSpools();if(!a.length){toast('No hay bobinas para exportar.');return}const rows=[['Material','Marca','Color','HEX/RGB','Peso inicial g','Peso restante g','Precio bobina'],...a.map(s=>[s.material,s.brand||'',s.colorName||s.color,s.hex||'',s.initial,s.remaining,s.price])];download(new Blob(['\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'Inventario_bobinas.csv')});
