function renderSpoolColorPalette(){const el=$('spoolColorPalette');if(!el)return;let custom=[];try{custom=JSON.parse(localStorage.getItem('pcp_custom_spool_colors')||'[]')}catch(e){}const all=[...basicSpoolColors,...custom.filter(c=>/^#[0-9a-f]{6}$/i.test(c)).map(hex=>({name:'Personalizado',hex:hex.toUpperCase()}))];el.innerHTML=all.map(c=>{const hex=c.hex.toUpperCase(),name=c.name,isCustom=name==='Personalizado';return `<span style="position:relative;display:inline-flex;justify-content:center"><button type="button" title="${name} · ${hex}" aria-label="Seleccionar ${name} ${hex}" data-spool-palette-color="${hex}" data-spool-palette-name="${name}" style="--spool-palette-color:${hex};height:25px;width:100%;min-width:20px;padding:0;border:1px solid ${hex==='#FFFFFF'?'#999':'#555'};border-radius:4px;background:${hex}!important;background-color:${hex}!important;cursor:pointer;box-shadow:${$('spoolColorPicker').value.toUpperCase()===hex?'0 0 0 2px var(--primary,#0d9488)':'none'}"></button>${isCustom?`<button type="button" title="Eliminar color personalizado ${hex}" aria-label="Eliminar color personalizado ${hex}" data-spool-palette-delete="${hex}" style="position:absolute;right:-5px;top:-7px;width:15px;height:15px;line-height:12px;padding:0;border-radius:50%;font-size:11px;background:#b91c1c;color:white;border:1px solid white;cursor:pointer">×</button>`:''}</span>`}).join('');/* v1.566: aplicar el color directamente como estilo prioritario para que el tema no lo tape. */el.querySelectorAll('#spoolColorPalette [data-spool-palette-color]').forEach(b=>{const hex=String(b.dataset.spoolPaletteColor||'#808080').toUpperCase();b.style.setProperty('background',hex,'important');b.style.setProperty('background-color',hex,'important');b.style.setProperty('background-image','none','important');b.style.setProperty('opacity','1','important');b.style.setProperty('filter','none','important');b.style.setProperty('min-height','25px','important');b.style.setProperty('height','25px','important');b.style.setProperty('border','1px solid '+(hex==='#FFFFFF'?'#777':'#64748b'),'important');});el.querySelectorAll('[data-spool-palette-color]').forEach(b=>b.addEventListener('click',async ()=>{$('spoolColorPicker').value=b.dataset.spoolPaletteColor;$('spoolColor').value=b.dataset.spoolPaletteName==='Personalizado'?'Personalizado '+b.dataset.spoolPaletteColor:b.dataset.spoolPaletteName;updateSpoolColorLabel(false);renderSpoolColorPalette()}));el.querySelectorAll('[data-spool-palette-delete]').forEach(b=>b.addEventListener('click',async e=>{e.stopPropagation();const hex=b.dataset.spoolPaletteDelete;if(!(await window.PCPConfirm(window.PCP_I18N.format('¿Eliminar el color personalizado {color} de la paleta?',{color:hex}))))return;let colors=[];try{colors=JSON.parse(localStorage.getItem('pcp_custom_spool_colors')||'[]')}catch(e){}localStorage.setItem('pcp_custom_spool_colors',JSON.stringify(colors.filter(c=>String(c).toUpperCase()!==hex.toUpperCase())));renderSpoolColorPalette();toast(window.PCP_I18N.t('Color personalizado eliminado de la paleta. Las bobinas existentes no se modifican.'))}));}
$('saveCustomSpoolColor').addEventListener('click',()=>{let a=[];try{a=JSON.parse(localStorage.getItem('pcp_custom_spool_colors')||'[]')}catch(e){}const c=$('spoolColorPicker').value.toUpperCase();if(!a.includes(c))a.push(c);localStorage.setItem('pcp_custom_spool_colors',JSON.stringify(a.slice(-30)));renderSpoolColorPalette();toast('Color personalizado guardado.')});
